/* @author MILO-GAO(高振銘)@2020 */ package page2020.flow;import java.util.Arrays;import org.slf4j.Logger;import org.slf4j.LoggerFactory;import page2020.core.App;import page2020.core.Flow;import page2020.core.Log;import page2020.unit.Func;import page2020.util.EmptyUtil;import page2020.view.B4;import page2020.view.H5;import page2020.view.bs4.B4element;import page2020.view.bs4.B4show.D;import page2020.view.html5.H5button;import page2020.view.html5.H5header;import page2020.view.html5.H5main;public class LayoutFlow extends DataFlow {	private static Logger log = LoggerFactory.getLogger(LayoutFlow.class);		protected H5header header;	protected B4element buttonBox;	protected H5main main;	@Override	public Flow automate() {		App app = super.page.getApp();		Personal personal = super.page.personal();		super.automate();		super.page.getScripts().addAll(personal.script());		Func func = App.funcProp.value(app.getAppCode());		this.header = personal.header(page, func);		this.buttonBox = personal.buttonBox(page, this.buttonBox(func));		this.main = personal.main(super.page, this.main());		super.page.append(			B4.element().append(				this.header, this.buttonBox, this.main		));				if (Log.flow) {			log.info(super.logName + "app='" + app.getName() + "', function='" + func.getName()				+ ", main.count=" + this.main.count() + ", header.count=" + this.header.count() 				+ ", buttonBox.count=" + this.buttonBox.count());		}		return this;	}	protected void disableButtons(String... buttonNames) {		if (EmptyUtil.not(buttonNames) && this.buttonBox.count() > 0) {			this.buttonBox.getContents().forEach(content -> {				if (content instanceof H5button) {					H5button button = (H5button) content;					Arrays.asList(buttonNames).forEach(name -> {						if (name.equals(button.getName())) {							button.disabled(true);							}					});				}			});		}	}	protected void hideButtons(String... buttonNames) {		if (EmptyUtil.not(buttonNames) && this.buttonBox.count() > 0) {			this.buttonBox.getContents().forEach(content -> {				if (content instanceof H5button) {					H5button button = (H5button) content;					Arrays.asList(buttonNames).forEach(name -> {						if (name.equals(button.getName())) {							button.cssClass(D.none);							}					});				}			});		}	}	private B4element buttonBox(Func func) {		B4element element = B4.element();		if (func != null && EmptyUtil.not(func.getButtons())) {			func.getButtons().forEach(btnName -> {				H5button button = App.button(btnName);				if (button == null) {					button = super.view.getButtons().remove(btnName); 				}				if (button != null) {					element.append(button);				}			});		} else if (super.view.getButtons().size() > 0) {			super.view.getButtons().forEach((btnName, button) -> element.append(button));			view.getButtons().clear();		}		return element;	}	private H5main main() {		H5main main = H5.main();		if (super.view.count() > 0) {			main.append(super.view.getContents());			super.view.empty();		}		if (super.forms.size() > 0) {			super.forms.forEach((name, child) -> {				if (super.view.equals(child.getElement())) {					child.setElement(main);				}			});		}		if (super.tables.size() > 0) {			super.tables.forEach((name, child) -> {				if (super.view.equals(child.getElement())) {					child.setElement(main);				}			});		}		return main;	}}